-- Guard against cadence validation succeeding for a non-existent relationship.
create or replace function public.aya_b2b_validate_cadence_change_v1(p_relationship_id uuid,p_from_cadence text,p_to_cadence text) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_paid bigint; v_committed bigint; v_rank_from integer; v_rank_to integer; v_exists boolean; begin select exists(select 1 from public.aya_b2b_relationships where id=p_relationship_id) into v_exists; if not v_exists then return jsonb_build_object('allowed',false,'reason','Relationship not found'); end if; v_rank_from:=case p_from_cadence when 'M2' then 4 when 'M1' then 3 when 'W2' then 2 when 'W1' then 1 else 0 end; v_rank_to:=case p_to_cadence when 'M2' then 4 when 'M1' then 3 when 'W2' then 2 when 'W1' then 1 else 0 end; if v_rank_from=0 or v_rank_to=0 then return jsonb_build_object('allowed',false,'reason','Cadence must be W1/W2/M1/M2'); end if; if v_rank_to>=v_rank_from then return jsonb_build_object('allowed',false,'reason','Cadence may only move toward more frequent delivery'); end if; select coalesce(sum(amount_verified_paid),0) into v_paid from public.aya_b2b_payment_obligations where relationship_id=p_relationship_id and status<>'cancelled'; select coalesce(total_committed_value,0) into v_committed from public.aya_b2b_commercial_summaries where relationship_id=p_relationship_id and status='confirmed' order by version_no desc limit 1; if v_committed=0 then return jsonb_build_object('allowed',false,'reason','Confirmed commitment value is not available'); end if; if v_paid*2<v_committed then return jsonb_build_object('allowed',false,'reason','Cadence change requires at least 50% of total commitment paid'); end if; return jsonb_build_object('allowed',true,'paid',v_paid,'committed',v_committed,'payment_protection',case when v_paid>=v_committed then '100%' else '50%' end); end; $$;
revoke all on function public.aya_b2b_validate_cadence_change_v1(uuid,text,text) from anon,authenticated;
